import { Pool } from 'pg';

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

export async function findUserByEmail(email) {
  // Parameterized query prevents SQL injection
  const { rows } = await pool.query(
    'SELECT id, username, email, role FROM users WHERE email = $1 AND is_active = TRUE',
    [email]
  );
  return rows[0] || null;
}

package main

import (
    "context"
    "github.com/jackc/pgx/v5/pgxpool"
)

type User struct {
    ID       int64  `json:"id"`
    Username string `json:"username"`
    Email    string `json:"email"`
    Role     string `json:"role"`
}

func FindUserByEmail(ctx context.Context, pool *pgxpool.Pool, email string) (*User, error) {
    var u User
    query := `SELECT id, username, email, role FROM users WHERE email = $1 AND is_active = true`
    err := pool.QueryRow(ctx, query, email).Scan(&u.ID, &u.Username, &u.Email, &u.Role)
    if err != nil {
        return nil, err
    }
    return &u, nil
}

